import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import static com.freshmart.operations.OperationsModels.*;

@Service @Transactional
public class OperationsService {
 private final OperationsMapper db;private final BusinessPolicyService policies;private final CheckoutMapper checkoutDb;
 private final CheckoutService checkout;private final MediaService media;private final Clock clock;private final ObjectMapper json;
 public OperationsService(OperationsMapper db,BusinessPolicyService policies,CheckoutMapper checkoutDb,CheckoutService checkout,MediaService media,Clock clock,ObjectMapper json){this.db=db;this.policies=policies;this.checkoutDb=checkoutDb;this.checkout=checkout;this.media=media;this.clock=clock;this.json=json;}
 private void operator(RequestActor a,String p){a.requireRole("OPERATOR");a.requirePermission(p);}
 private void picker(RequestActor a,String p){a.requireRole("PICKER");a.requirePermission(p);}
 @Transactional(readOnly=true) public PageResult<AdminProduct> products(RequestActor a,int page,int size,String status){operator(a,"product.read");paging(page,size);oneOf(status,Set.of("DRAFT","ON_SALE","OFF_SALE"),true,"商品状态");var policy=policies.current();return new PageResult<>(page,size,db.productCount(status),db.products(status,size,offset(page,size)).stream().map(p->productView(p,policy)).toList());}
 @Transactional(readOnly=true) public AdminProduct product(RequestActor a,String id){operator(a,"product.read");return productView(requireProduct(id,false),policies.current());}
 public AdminProduct createProduct(RequestActor a,ProductWrite in){operator(a,"product.write");category(in.categoryId());image(in.imageUrl());String id=id();var row=new ProductRow(id,"SPU-"+id,in.categoryId(),in.name().trim(),in.description().trim(),in.origin().trim(),in.storage(),in.imageUrl(),"DRAFT",0);db.insertProduct(row,clock.instant());audit(a,"product.create","PRODUCT",id,"新建商品草稿",null,row);return productView(row,policies.current());}
 public AdminProduct patchProduct(RequestActor a,String id,JsonNode patch){operator(a,"product.write");patch(patch,Set.of("categoryId","name","description","origin","storage","imageUrl","version"));var old=requireProduct(id,true);version(old.version(),number(patch,"version",0,MAX));String category=text(patch,"categoryId",old.categoryId(),64),name=text(patch,"name",old.name(),120),description=text(patch,"description",old.description(),4000),origin=text(patch,"origin",old.origin(),100),storage=text(patch,"storage",old.storage(),16),image=text(patch,"imageUrl",old.imageUrl(),2048);identifier(category);category(category);oneOf(storage,Set.of("AMBIENT","COLD","FROZEN","LIVE"),false,"储存方式");image(image);var row=new ProductRow(old.productId(),old.spuCode(),category,name,description,origin,storage,image,old.status(),old.version());if(db.updateProduct(row,clock.instant())!=1)throw stale();var changed=requireProduct(id,false);audit(a,"product.update","PRODUCT",id,"修改商品资料；历史成交快照保留",old,changed);return productView(changed,policies.current());}
 public AdminProduct productStatus(RequestActor a,String id,ProductStatus in){operator(a,"product.status");var old=requireProduct(id,true);version(old.version(),in.version());if(in.status().equals("ON_SALE")){category(old.categoryId());image(old.imageUrl());var active=db.skus(id).stream().filter(s->s.status().equals("ACTIVE")).toList();if(active.isEmpty())throw invalidState("至少配置一个有效SKU后才能上架");for(var sku:active){units(sku.baseUnit(),sku.priceMode(),sku.priceUnitGram());prices(sku.price(),sku.memberPrice());image(sku.imageUrl());}}var row=new ProductRow(old.productId(),old.spuCode(),old.categoryId(),old.name(),old.description(),old.origin(),old.storage(),old.imageUrl(),in.status(),old.version());if(db.updateProduct(row,clock.instant())!=1)throw stale();var changed=requireProduct(id,false);audit(a,"product.status","PRODUCT",id,"商品上架/下架",old,changed);return productView(changed,policies.current());}
 public SkuView createSku(RequestActor a,String productId,SkuWrite in){operator(a,"sku.write");requireProduct(productId,true);if(db.skus(productId).size()>=100)throw ApiException.invalid("每个商品最多100个SKU");units(in.baseUnit(),in.priceMode(),in.priceUnitGram());prices(in.price(),in.memberPrice());image(in.imageUrl());if(db.skuCodeCount(in.skuCode(),"")>0)throw ApiException.conflict("SKU编码已存在");String id=id();var row=new SkuRow(id,in.skuCode(),productId,in.name().trim(),in.unitLabel().trim(),in.baseUnit(),in.priceMode(),in.priceUnitGram(),in.price(),in.memberPrice(),in.imageUrl(),"ACTIVE",0);db.insertSku(row,clock.instant());audit(a,"sku.create","SKU",id,"创建商品规格",null,row);return skuView(row,policies.current());}
 public SkuView patchSku(RequestActor a,String id,JsonNode patch){operator(a,"sku.write");patch(patch,Set.of("skuCode","name","unitLabel","baseUnit","priceMode","priceUnitGram","price","memberPrice","imageUrl","version"));var old=requireSku(id,true);requireProduct(old.productId(),true);version(old.version(),number(patch,"version",0,MAX));String code=text(patch,"skuCode",old.skuCode(),64),name=text(patch,"name",old.name(),120),label=text(patch,"unitLabel",old.unitLabel(),60),base=text(patch,"baseUnit",old.baseUnit(),10),mode=text(patch,"priceMode",old.priceMode(),16),image=text(patch,"imageUrl",old.imageUrl(),2048);identifier(code);Long grams=patch.has("priceUnitGram")?(patch.get("priceUnitGram").isNull()?null:number(patch,"priceUnitGram",1,MAX)):old.priceUnitGram();long price=patch.has("price")?number(patch,"price",0,MAX):old.price(),member=patch.has("memberPrice")?number(patch,"memberPrice",0,MAX):old.memberPrice();units(base,mode,grams);prices(price,member);image(image);if((!base.equals(old.baseUnit())||!mode.equals(old.priceMode()))&&db.skuBatchCount(id)>0)throw invalidState("已有库存台账的SKU不能改变计量基础单位；请新建SKU");if(db.skuCodeCount(code,id)>0)throw ApiException.conflict("SKU编码已存在");var row=new SkuRow(id,code,old.productId(),name,label,base,mode,grams,price,member,image,old.status(),old.version());if(db.updateSku(row,clock.instant())!=1)throw stale();var changed=requireSku(id,false);audit(a,"sku.update","SKU",id,"修改SKU；旧订单价格规格快照不变",old,changed);return skuView(changed,policies.current());}
 @Transactional(readOnly=true) public PageResult<Batch> batches(RequestActor a,int page,int size,String sku,String lifecycle,String freshness){picker(a,"batch.read");paging(page,size);if(sku!=null)identifier(sku);oneOf(lifecycle,Set.of("NORMAL","QUARANTINED","DISPOSED"),true,"批次生命周期");oneOf(freshness,Set.of("NORMAL","NEAR_EXPIRY","EXPIRED"),true,"批次鲜度");Instant now=clock.instant(),near=now.plus(Duration.ofDays(policies.current().nearExpiryDays()));return new PageResult<>(page,size,db.batchCount(sku,lifecycle,freshness,now,near),db.batches(sku,lifecycle,freshness,now,near,size,offset(page,size)).stream().map(b->batchView(b,now,near)).toList());}
 @Transactional(readOnly=true) public Batch batch(RequestActor a,String id){picker(a,"batch.read");return batchView(requireBatch(id,false));}
 public Batch createBatch(RequestActor a,BatchCreate in){picker(a,"batch.create");var sku=requireSku(in.skuId(),true);if(!sku.status().equals("ACTIVE"))throw invalidState("停用SKU不能入库");Instant now=clock.instant();if(in.producedAt().isAfter(now)||!in.expiresAt().isAfter(now)||!in.expiresAt().isAfter(in.producedAt()))throw ApiException.invalid("生产时间不能晚于验收入库，到期时间必须在入库和生产之后");if(db.batchNoCount(in.skuId(),in.batchNo())>0)throw ApiException.conflict("该SKU批次号已存在，不能重复记入库存");String id=id();var row=new BatchRow(id,in.batchNo(),in.skuId(),sku.baseUnit(),in.receivedQuantity(),0,0,"NORMAL",in.producedAt(),in.expiresAt(),now,0);db.insertBatch(row,now);db.movement(id(),id,"RECEIVE",row.onHand(),0,0,in.reason().trim(),a.userId(),now);audit(a,"batch.receive","BATCH",id,in.reason().trim(),null,row);return batchView(row);}
 public Batch adjust(RequestActor a,String id,Adjustment in){picker(a,"inventory.adjust");var row=lockBatchWithSku(id);version(row.version(),in.version());if(row.lifecycle().equals("DISPOSED"))throw invalidState("已报废批次不能调整或恢复");long delta=in.quantityDelta();if(delta==0)throw ApiException.invalid("数量调整不能为0");if(!in.reasonCode().equals("COUNT_CORRECTION")&&delta>0)throw ApiException.invalid("损耗和过期报废只允许减少数量");if(in.reasonCode().equals("EXPIRED_DISPOSAL")&&row.expiresAt().isAfter(clock.instant()))throw ApiException.invalid("未过期批次不能标记过期报废");long hand=bounded(BigInteger.valueOf(row.onHand()).add(BigInteger.valueOf(delta)));long quarantine=row.quarantined();if(row.lifecycle().equals("QUARANTINED"))quarantine=hand;if(hand<row.reserved()+quarantine)throw insufficient("调整不能侵占已预占或隔离数量");String lifecycle=in.reasonCode().equals("EXPIRED_DISPOSAL")&&hand==0?"DISPOSED":row.lifecycle();var changed=balance(row,hand,row.reserved(),quarantine,lifecycle);if(db.updateBatch(changed,clock.instant())!=1)throw stale();db.movement(id(),id,in.reasonCode().equals("EXPIRED_DISPOSAL")?"DISPOSE":"ADJUST",delta,0,quarantine-row.quarantined(),in.reason().trim(),a.userId(),clock.instant());audit(a,"inventory.adjust","BATCH",id,in.reason().trim(),row,Map.of("reasonCode",in.reasonCode(),"balance",changed));return batchView(requireBatch(id,false));}
 public Batch lifecycle(RequestActor a,String id,Lifecycle in){picker(a,"batch.lifecycle");var row=lockBatchWithSku(id);version(row.version(),in.version());if(row.lifecycle().equals("DISPOSED"))throw invalidState("已报废批次不可恢复或再次报废");if(row.reserved()>0)throw invalidState("批次仍有未履约预占，须先处理对应订单/分配");if(in.lifecycle().equals("NORMAL")&&!row.expiresAt().isAfter(clock.instant()))throw invalidState("过期是派生鲜度，不能通过恢复NORMAL重新销售");long hand=in.lifecycle().equals("DISPOSED")?0:row.onHand(),quarantine=in.lifecycle().equals("QUARANTINED")?hand:0;var changed=balance(row,hand,0,quarantine,in.lifecycle());if(db.updateBatch(changed,clock.instant())!=1)throw stale();String type=in.lifecycle().equals("DISPOSED")?"DISPOSE":in.lifecycle().equals("QUARANTINED")?"QUARANTINE":"ADJUST";db.movement(id(),id,type,hand-row.onHand(),0,quarantine-row.quarantined(),in.reason().trim(),a.userId(),clock.instant());audit(a,"batch.lifecycle","BATCH",id,in.reason().trim(),row,changed);return batchView(requireBatch(id,false));}
 @Transactional(readOnly=true) public PageResult<Movement> movements(RequestActor a,int page,int size,String batch,String order){a.requireAnyRole("PICKER","FINANCE");a.requirePermission("inventory.movement.read");paging(page,size);if(batch!=null)identifier(batch);if(order!=null)identifier(order);boolean finance=a.roles().contains("FINANCE");var rows=db.movements(batch,order,finance,size,offset(page,size));if(finance)rows=rows.stream().map(m->new Movement(m.movementId(),m.batchId(),m.skuId(),m.orderId(),m.type(),m.onHandDelta(),m.reservedDelta(),m.quarantinedDelta(),"订单库存业务："+m.type(),"system-audit",m.createdAt())).toList();return new PageResult<>(page,size,db.movementCount(batch,order,finance),rows);}
 @Transactional(readOnly=true) public Map<String,List<SlotView>> slots(RequestActor a,LocalDate date){operator(a,"slot.manage");return Map.of("items",checkoutDb.slots(date).stream().map(s->checkout.slotView(s,true)).toList());}
 public SlotView updateSlot(RequestActor a,String id,SlotUpdate in){operator(a,"slot.manage");identifier(id);var old=checkoutDb.lockSlot(id);if(old==null)throw ApiException.notFound();version(old.version(),in.version());if(in.capacity()<old.used())throw invalidState("容量不能小于已预约数量");if(in.cutoffAt().isAfter(old.startAt()))throw ApiException.invalid("预约截止不能晚于配送开始");if(db.updateSlot(id,in)!=1)throw stale();var changed=checkoutDb.slot(id);audit(a,"slot.update","DELIVERY_SLOT",id,"修改配送容量/截止/启用状态",old,changed);return checkout.slotView(changed,true);}
 @Transactional(readOnly=true) public Policies policies(RequestActor a){operator(a,"policy.manage");return policies.current();}
 public Policies updatePolicies(RequestActor a,Policies in){operator(a,"policy.manage");var old=policies.lockCurrent();version(old.version(),in.version());if(db.updatePolicies(in,clock.instant())!=1)throw stale();db.updateNewcomer(in);var changed=policies.current();audit(a,"policy.update","BUSINESS_POLICY","STORE","限定业务规则立即影响新报价与新发券；历史快照保留",old,changed);return changed;}

 private AdminProduct productView(ProductRow p,Policies policy){var raw=db.skus(p.productId());var batches=db.skuBatches(raw.stream().map(SkuRow::skuId).toList()).stream().collect(java.util.stream.Collectors.groupingBy(BatchRow::skuId));var skus=raw.stream().map(s->skuView(s,policy,batches.getOrDefault(s.skuId(),List.of()))).toList();var activeIds=raw.stream().filter(s->s.status().equals("ACTIVE")).map(SkuRow::skuId).collect(java.util.stream.Collectors.toSet());var active=skus.stream().filter(s->activeIds.contains(s.skuId())).toList();var first=active.stream().min(Comparator.comparingLong(SkuView::salePrice).thenComparing(SkuView::skuId)).orElse(null);var earliest=active.stream().filter(s->s.shelfLifeRemainingDays()!=null).min(Comparator.comparingLong(SkuView::shelfLifeRemainingDays)).orElse(null);boolean near=active.stream().anyMatch(SkuView::nearExpiry);String stock=active.stream().anyMatch(s->s.stockStatus().equals("IN_STOCK"))?"IN_STOCK":active.stream().anyMatch(s->s.stockStatus().equals("LOW"))?"LOW":"SOLD_OUT";return new AdminProduct(p.productId(),p.spuCode(),p.categoryId(),p.name(),p.description(),p.origin(),p.storage(),p.imageUrl(),first==null?0:first.price(),first==null?0:first.memberPrice(),first==null?0:first.salePrice(),first==null?"BY_PIECE":first.priceMode(),first==null?"未配置规格":first.unitLabel(),stock,near,skus,p.version(),p.status(),earliest==null?null:earliest.arrivedAt(),earliest==null?null:near?"NEAR_EXPIRY":"NORMAL",earliest==null?null:earliest.shelfLifeRemainingDays());}
 private SkuView skuView(SkuRow s,Policies p){return skuView(s,p,db.skuBatches(s.skuId()));}
 private SkuView skuView(SkuRow s,Policies p,List<BatchRow> source){Instant now=clock.instant(),near=now.plus(Duration.ofDays(p.nearExpiryDays()));var batches=s.status().equals("ACTIVE")?source.stream().filter(b->b.expiresAt().isAfter(now)&&!b.receivedAt().isAfter(now)).toList():List.<BatchRow>of();var candidate=batches.isEmpty()?null:batches.getFirst();long available=batches.stream().map(b->BigInteger.valueOf(b.onHand()-b.reserved()-b.quarantined())).reduce(BigInteger.ZERO,BigInteger::add).min(BigInteger.valueOf(MAX)).longValueExact();boolean isNear=candidate!=null&&!candidate.expiresAt().isAfter(near);long sale=isNear?Math.min(s.memberPrice(),BigInteger.valueOf(s.price()).multiply(BigInteger.valueOf(p.nearExpiryDiscountBasisPoints())).add(BigInteger.valueOf(5000)).divide(BigInteger.valueOf(10000)).longValueExact()):s.memberPrice();String stock=available==0?"SOLD_OUT":available<=(s.baseUnit().equals("GRAM")?5000:5)?"LOW":"IN_STOCK";return new SkuView(s.skuId(),s.skuCode(),s.name(),s.unitLabel(),s.baseUnit(),s.priceMode(),s.priceUnitGram(),s.price(),s.memberPrice(),sale,stock,isNear,s.imageUrl(),s.version(),candidate==null?null:candidate.receivedAt().toString(),candidate==null?null:isNear?"NEAR_EXPIRY":"NORMAL",candidate==null?null:Duration.between(now,candidate.expiresAt()).toDays());}
 private Batch batchView(BatchRow b){Instant now=clock.instant();return batchView(b,now,now.plus(Duration.ofDays(policies.current().nearExpiryDays())));}
 private Batch batchView(BatchRow b,Instant now,Instant near){String freshness=!b.expiresAt().isAfter(now)?"EXPIRED":!b.expiresAt().isAfter(near)?"NEAR_EXPIRY":"NORMAL";return new Batch(b.batchId(),b.batchNo(),b.skuId(),b.baseUnit(),b.onHand(),b.reserved(),b.quarantined(),b.onHand()-b.reserved()-b.quarantined(),b.lifecycle(),freshness,b.producedAt()==null?null:b.producedAt().toString(),b.expiresAt().toString(),b.receivedAt().toString(),b.version());}
 private BatchRow balance(BatchRow b,long hand,long reserved,long quarantine,String lifecycle){return new BatchRow(b.batchId(),b.batchNo(),b.skuId(),b.baseUnit(),hand,reserved,quarantine,lifecycle,b.producedAt(),b.expiresAt(),b.receivedAt(),b.version());}
 private BatchRow lockBatchWithSku(String id){var initial=requireBatch(id,false);requireSku(initial.skuId(),true);return requireBatch(id,true);}
 private ProductRow requireProduct(String id,boolean lock){identifier(id);var value=db.product(id,lock);if(value==null)throw ApiException.notFound();return value;}
 private SkuRow requireSku(String id,boolean lock){identifier(id);var value=db.sku(id,lock);if(value==null)throw ApiException.notFound();return value;}
 private BatchRow requireBatch(String id,boolean lock){identifier(id);var value=db.batch(id,lock);if(value==null)throw ApiException.notFound();return value;}
 private void category(String id){if(!db.categoryEnabled(id))throw ApiException.invalid("分类不存在或未启用");}
 private void image(String url){media.requirePublicProductUrl(url);}
 private void units(String base,String mode,Long gram){if(!(base.equals("PIECE")&&mode.equals("BY_PIECE")&&gram==null)&&!(base.equals("GRAM")&&mode.equals("BY_WEIGHT")&&gram!=null&&gram>0&&gram<=MAX))throw ApiException.invalid("计量基础单位、计价方式和单价克数不匹配");}
 private void prices(long price,long member){if(price<0||price>MAX||member<0||member>price)throw ApiException.invalid("会员价不得高于参考价，金额须为安全整数分");}
 private void patch(JsonNode node,Set<String> allowed){if(!node.isObject()||node.size()<2||!node.has("version"))throw ApiException.invalid("至少提供一个修改字段和version");for(var name:node.propertyNames())if(!allowed.contains(name))throw ApiException.invalid("不支持的修改字段："+name);}
 private String text(JsonNode node,String name,String fallback,int max){if(!node.has(name))return fallback;var n=node.get(name);if(!n.isString()||n.asString().isBlank()||n.asString().length()>max)throw ApiException.invalid(name+"格式或长度不合法");return n.asString().trim();}
 private long number(JsonNode node,String name,long min,long max){var n=node.get(name);if(n==null||!n.isIntegralNumber()||!n.canConvertToLong()||n.asLong()<min||n.asLong()>max)throw ApiException.invalid(name+"必须是允许范围内的整数");return n.asLong();}
 private void oneOf(String value,Set<String> allowed,boolean nullable,String field){if(value==null&&nullable)return;if(!allowed.contains(value))throw ApiException.invalid(field+"不合法");}
 private void identifier(String value){if(value==null||!value.matches("[A-Za-z0-9_-]{1,64}"))throw ApiException.invalid("ID格式不合法");}
 private void paging(int page,int size){if(page<1||size<1||size>100)throw ApiException.invalid("page从1开始，size为1至100");}
 private long offset(int page,int size){return ((long)page-1)*size;}
 private void version(long actual,long expected){if(actual!=expected)throw stale();}
 private ApiException stale(){return ApiException.conflict("资源已变更，请刷新后重试");}
 private ApiException invalidState(String message){return new ApiException(409,1007,"INVALID_STATE",message);}
 private ApiException insufficient(String message){return new ApiException(422,1201,"INSUFFICIENT_STOCK",message);}
 private long bounded(BigInteger n){if(n.signum()<0||n.compareTo(BigInteger.valueOf(MAX))>0)throw insufficient("库存数量不足或超出安全整数范围");return n.longValueExact();}
 private void audit(RequestActor a,String op,String type,String resource,String reason,Object before,Object after){db.audit(id(),a.userId(),op,type,resource,reason,before==null?null:json.writeValueAsString(before),after==null?null:json.writeValueAsString(after),TraceContext.id(),clock.instant(),String.join(",",a.roles().stream().sorted().toList()),"SUCCESS");}
 private String id(){return UUID.randomUUID().toString();}
}
